import{_ as t,o,c as _,ag as e}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第89章 它会自己跳上来","description":"","frontmatter":{},"headers":[],"relativePath":"第89章_它会自己跳上来.md","filePath":"第89章_它会自己跳上来.md"}'),a={name:"第89章_它会自己跳上来.md"};function r(u,p,n,s,q,c){return o(),_("div",null,[...p[0]||(p[0]=[e('<h1 id="第89章-它会自己跳上来" tabindex="-1">第89章 它会自己跳上来 <a class="header-anchor" href="#第89章-它会自己跳上来" aria-label="Permalink to &quot;第89章 它会自己跳上来&quot;">​</a></h1><p>三月有一天，她在旧号上发了一条朋友圈。</p><p>旧号是她妈看的。</p><p>那条我到现在还留着截图。</p><p>那是一张猫。</p><p>那只猫是她姨家楼下那只，她给我喂过，她给它起了一个很难听的名字。</p><p>照片里那只猫蹲在窗台上，外面在下雨，玻璃上有一道一道的水。</p><p>配的文字是七个字：</p><p>&quot;它会自己跳上来。&quot;</p><p>底下有二十几个赞。</p><p>她姨评论说，这猫真肥。</p><p>她一个叔叔说，那边冬天冷，别开窗。</p><p>她妈没有评论。</p><p>她妈那天在她那条底下回了一句&quot;吃了吗&quot;，回的是上一条。</p><p>我看到那七个字，坐在椅子上，一动不动。</p><p>因为那是一年前的话。</p><p>那年十二月，她跟我讲她那个天花板漏水。</p><p>她讲她把本子挪到柜子最上面一层。</p><p>她说挪到别人够不着的地方就安全了。</p><p>我说，那你那个猫呢。</p><p>她说，猫不用挪。</p><p>她说，猫是自己会跳上窗台的。</p><p>那天晚上她把这句话，原样发到了一台她妈能看见的手机上。</p><p>她换了一个说法。</p><p>她把&quot;不用挪&quot;省掉了。</p><p>她只留下&quot;它会自己跳上来&quot;。</p><p>她给所有人看的是一只猫。</p><p>她给我看的是：我那天跟你讲的每一句，我自己记得。</p><p>我那时候手已经放在那个&quot;赞&quot;上面了。</p><p>我停住了。</p><p>我停住的原因很简单。</p><p>二月那年我在那个号上留了一句&quot;那边橙子便宜&quot;。</p><p>那次代价是：她妈当天把她手机收走，她一个晚上没有号。</p><p>这次不一样。</p><p>这次她发的是一条有二十几个人赞的东西。</p><p>我要是在这条下面出现一次，她妈会看见一个陌生的名字，给一张猫的照片点赞。</p><p>她妈会问一句。</p><p>她又要编。</p><p>她编的东西第二天要认。</p><p>我把手收回来。</p><p>我把那张截图存下来。</p><p>存完我把手机扣在桌上，去洗了脸。</p><p>那天晚上十一点，她的新号上线了。</p><p>她第一句就是：</p><p>她说，你没点。</p><p>我说，我不能点。</p><p>她说，我知道。</p><p>她说，我今天等了一下午。</p><p>我说，你等的是我点不点。</p><p>她说，我等的不是这个。</p><p>她说，我要的是你看懂没有。</p><p>我说，我看懂了。</p><p>她说，你讲。</p><p>我说，你说的是那天晚上那只猫。</p><p>我说，你说的是本子挪到最上面，猫不用挪。</p><p>我说，你把它发在一个所有人都只会看见猫的地方。</p><p>她说，对。</p><p>她说，我今天讲一下我今天为什么发这条。</p><p>她说，我今天下午在那个走廊上，我把那个布拿回来了。</p><p>她说，就是一块布，接天花板那个水的。</p><p>她说，我拿着那块布上楼，我走到三楼的时候我停了一下。</p><p>她说，我那时候心里想了一句很难听的话。</p><p>我说，什么。</p><p>她说，我想，我这一天要是有人能看见我拿着这块布，我就不用自己知道这事有多可笑。</p><p>她说，我就上去把手机拿起来了。</p><p>她说，我本来要打一句别的。</p><p>她说，我打的是&quot;我今天领了一块布回来&quot;。</p><p>她说，我打完我看了一眼，我觉得这句太真了。</p><p>她说，真到我妈会问为什么领布。</p><p>她说，我就删了。</p><p>她说，我删完我在相册里翻，我翻到那只猫。</p><p>她说，我就发了那七个字。</p><p>我说，那七个字你是从我那儿拿的。</p><p>她说，对。</p><p>她说，我从你那儿拿的，我发到我妈看得见的地方。</p><p>她说，我想看看这个东西能不能在两个地方同时活。</p><p>她说，在我妈那边它是一只肥猫。</p><p>她说，在你那边它是那天晚上。</p><p>她说，我今天发现它可以同时在。</p><p>我说，那你今天高兴吗。</p><p>她隔了很久。</p><p>然后她说了一句。</p><p>她说，我今天不难受。</p><p>她说，我这半年第一次不难受。</p><p>她说，我今天做了一件只有我知道的事，可是它写在一个所有人都看得见的地方。</p><p>她说，我以前以为这个东西叫藏。</p><p>她说，我今天觉得这叫活。</p><p>我说，那我没点你没难受？</p><p>她说，我难受了半分钟。</p><p>她说，半分钟以后我就想明白了。</p><p>她说，你不点才是对的。</p><p>她说，你要是点了，我今天这条就变成我们两个的事了。</p><p>她说，我们两个的事一变成事，我就得处理。</p><p>她说，我今天不想处理。</p><p>她说，我今天就想让那条猫待在那儿。</p><p>那天夜里我在本子上抄了那七个字。</p><p>抄完我在下面写：</p><p>她发在她的牢里，我读在我的牢外。</p><p>我们两个都不出声，这件事就成了。</p><p>第二天那条朋友圈还在。</p><p>第三天那条被删了。</p><p>她没跟我说是她删的还是她妈让她删的。</p><p>我也没问。</p><p>我手里有那张截图。</p><p>她那一年在旧号上发过四十多条，我全部截了。</p><p>这件事我也从来没有讲过。</p><p>四月我也试了一次。</p><p>我那天在食堂听见有人放我们高中那首歌。</p><p>我拿手机拍了一段十五秒。</p><p>拍的是一个胋子的顶，和那个挂墙的喇叭。</p><p>我本来要配一句：“它会自己跳上来。”</p><p>我知道那句不行。</p><p>那不是我的。</p><p>我想了二十分钟，我配了一句：“今天风大。”</p><p>我按发送。</p><p>发完我拿着手机坐在那个大胋子里，等了半个钟头。</p><p>有十九个人点赞。</p><p>六条评论。</p><p>一个说，你去哪儿了。</p><p>一个说，这个喇叭我认识。</p><p>我妈评论了一个笑脸。</p><p>没有一个人看见那四个字里有什么。</p><p>也没有一个人能看见。</p><p>因为我这边没有人查我。</p><p>我这边没有一台每个星期要被拿起来看一下的手机。</p><p>我这边没有一个会问我“这个我们是谁”的人。</p><p>我那句话不是藏在一个所有人只看得到猫的地方。</p><p>我那句话就是没人在找。</p><p>我那天晚上把那条删了。</p><p>删完我给她发了一句。</p><p>我说，我今天也发了一条。</p><p>她说，发的什么。</p><p>我说，今天风大。</p><p>她隔了很久。</p><p>她说，你删了。</p><p>我说，你怎么知道。</p><p>她说，因为我这边发一条，我要看它能活多久。</p><p>她说，你那边发一条，你等不到半小时你就会删。</p><p>她说，因为你那边没有人在查你。</p><p>她说，你藏的东西不是怕人看见。</p><p>她说，你是怕人没看见。</p><p>我看到这一句，坐在那台胋子的椅子上。</p><p>周围六十多个人。</p><p>我把那十五秒的规频从相册里也删了。</p><p>我手里只剩下那张猫。</p><p>那天夜里我在本子上写了一行。</p><p>我写：她那边有一面墙，她把话写在墙后面。</p><p>我写：我这边四面都是空的，我把话写在手上，写完了我自己擦。</p>',148)])])}const l=t(a,[["render",r]]);export{d as __pageData,l as default};
